  const positional: string[] = [];

  for (const arg of withoutNodeArgumentSeparator(argv)) {
    if (!parseFlags) {
      positional.push(arg);
      continue;
    }

    if (arg === '--') {
      parseFlags = false;
      continue;
    }

    switch (arg) {
      case '--mock':
        mock = true;
        break;
      case '--no-trace':
        noTrace = true;
        break;
      case '--json':
        json = true;
        break;
      case '--help':
      case '-h':
        showHelp = true;
        break;
      case '--version':
        showVersion = true;
        break;
      default:
        if (arg.startsWith('-')) {
          throw usageError(`Unknown option: ${arg}`);
        }
