123	    '!traces/**',
124	    '--glob',
125	    '!**/.env',
126	    '--glob',
127	    '!**/.env.*',
128	    '--glob',
129	    '!**/credentials*',
130	    '--glob',
131	    '!**/secrets*',
132	    '--glob',
