  6	export const MAX_TOOL_OUTPUT_BYTES = 16 * 1024;
  7	export const MAX_SEARCH_RESULTS = 50;
  8	export const MAX_READ_FILE_BYTES = 64 * 1024;
  9	export const SEARCH_TIMEOUT_MS = 10_000;
 10	export const VALIDATION_TIMEOUT_MS = 120_000;
 11	
 12	export type ProcessRequest = {
 13	  command: string;
 14	  args: string[];
 15	  cwd: string;
 16	  timeoutMs: number;
 17	};
 18	
 19	export type ProcessResult = {
 20	  exitCode: number | null;
 21	  stdout: string;
 22	  stderr: string;
 23	  timedOut: boolean;
 24	};
 25	
 26	export type ProcessRunner = (request: ProcessRequest) => Promise<ProcessResult>;
 27	
 28	export type ToolResult = {
 29	  action: CandidateProposal['action'];
 30	  ok: boolean;
 31	  exitCode: number | null;
 32	  durationMs: number;
 33	  timedOut: boolean;
 34	  output: string;
 35	  files: string[];
 36	};
 37	
 38	export class ToolExecutionError extends Error {
 39	  constructor(message: string) {
 40	    super(message);
 41	    this.name = 'ToolExecutionError';
 42	  }
 43	}
 44	
 45	function appendBounded(current: Buffer[], chunk: Buffer, byteCount: { value: number }): void {
 46	  const available = MAX_TOOL_OUTPUT_BYTES - byteCount.value;
 47	  if (available <= 0) return;
 48	  const bounded = chunk.subarray(0, available);
 49	  current.push(bounded);
 50	  byteCount.value += bounded.length;
 51	}
 52	
 53	export const runProcess: ProcessRunner = async (request) => new Promise((resolve, reject) => {
 54	  const child = spawn(request.command, request.args, {
 55	    cwd: request.cwd,
 56	    env: process.env,
 57	    shell: false,
 58	    stdio: ['ignore', 'pipe', 'pipe'],
 59	  });
 60	  const stdout: Buffer[] = [];
 61	  const stderr: Buffer[] = [];
 62	  const stdoutBytes = { value: 0 };
 63	  const stderrBytes = { value: 0 };
 64	  let timedOut = false;
 65	  let settled = false;
 66	  const timeout = setTimeout(() => {
 67	    timedOut = true;
 68	    child.kill('SIGTERM');
 69	  }, request.timeoutMs);
 70	  timeout.unref();
 71	
 72	  child.stdout.on('data', (chunk: Buffer) => appendBounded(stdout, chunk, stdoutBytes));
 73	  child.stderr.on('data', (chunk: Buffer) => appendBounded(stderr, chunk, stderrBytes));
 74	  child.on('error', (error) => {
 75	    if (settled) return;
 76	    settled = true;
 77	    clearTimeout(timeout);
 78	    reject(new ToolExecutionError(`Unable to start ${request.command}: ${error.message}`));
 79	  });
 80	  child.on('close', (exitCode) => {
 81	    if (settled) return;
 82	    settled = true;
 83	    clearTimeout(timeout);
 84	    resolve({
 85	      exitCode,
 86	      stdout: Buffer.concat(stdout).toString('utf8'),
 87	      stderr: Buffer.concat(stderr).toString('utf8'),
 88	      timedOut,
 89	    });
 90	  });
 91	});
 92	
 93	function validateProcessResult(result: ProcessResult): void {
 94	  if (
 95	    (result.exitCode !== null && !Number.isInteger(result.exitCode)) ||
 96	    typeof result.stdout !== 'string' ||
 97	    typeof result.stderr !== 'string' ||
 98	    typeof result.timedOut !== 'boolean'
 99	  ) {
100	    throw new ToolExecutionError('The process runner returned a malformed result.');
101	  }
102	}
103	
104	function normalizedOutput(result: ProcessResult): string {
105	  const combined = [result.stdout.trim(), result.stderr.trim()].filter(Boolean).join('\n');
106	  return combined || (result.timedOut ? 'Process timed out.' : 'Process produced no output.');
107	}
