109	function searchArgs(terms: string[]): string[] {
110	  const patterns = terms.flatMap((term) => ['-e', term]);
111	  return [
112	    '--files-with-matches',
113	    '--fixed-strings',
114	    '--ignore-case',
115	    '--hidden',
116	    '--glob',
117	    '!.git/**',
118	    '--glob',
119	    '!node_modules/**',
120	    '--glob',
121	    '!dist/**',
122	    '--glob',
123	    '!traces/**',
124	    '--glob',
125	    '!**/.env',
126	    '--glob',
127	    '!**/.env.*',
128	    '--glob',
129	    '!**/credentials*',
130	    '--glob',
131	    '!**/secrets*',
132	    '--glob',
133	    '!**/*.pem',
134	    '--glob',
135	    '!**/*.key',
136	    ...patterns,
137	    '.',
138	  ];
139	}
140	
141	function normalizeSearchFiles(stdout: string): string[] {
142	  return stdout
143	    .split(/\r?\n/u)
144	    .map((entry) => entry.replace(/^\.\//u, '').trim())
