169	  const preferences = ['README.md', 'package.json', 'PLAN.md'];
170	
171	  const sortedKnownPaths = knownPaths.sort((left, right) => {
172	    const leftIndex = preferences.indexOf(left);
173	    const rightIndex = preferences.indexOf(right);
174	    const leftRank = leftIndex === -1 ? preferences.length : leftIndex;
175	    const rightRank = rightIndex === -1 ? preferences.length : rightIndex;
176	    return leftRank - rightRank || left.localeCompare(right);
