 38	export class ToolExecutionError extends Error {
 39	  constructor(message: string) {
 40	    super(message);
 41	    this.name = 'ToolExecutionError';
 42	  }
 43	}
 44	
 45	function appendBounded(current: Buffer[], chunk: Buffer, byteCount: { value: number }): void {
 46	  const available = MAX_TOOL_OUTPUT_BYTES - byteCount.value;
 47	  if (available <= 0) return;
 48	  const bounded = chunk.subarray(0, available);
 49	  current.push(bounded);
 50	  byteCount.value += bounded.length;
 51	}
