118	    '--glob',
119	    '!node_modules/**',
120	    '--glob',
121	    '!dist/**',
122	    '--glob',
123	    '!traces/**',
124	    '--glob',
125	    '!**/.env',
126	    '--glob',
127	    '!**/.env.*',
128	    '--glob',
129	    '!**/credentials*',
130	    '--glob',
131	    '!**/secrets*',
132	    '--glob',
133	    '!**/*.pem',
134	    '--glob',
135	    '!**/*.key',
136	    ...patterns,
137	    '.',
138	  ];
139	}
