151	async function executeRead(proposal: Extract<CandidateProposal, { action: 'READ_FILE' }>): Promise<ToolResult> {
152	  const startedAt = performance.now();
153	  const safeRelativePath = await resolveSafeRepoFile(proposal.input.root, proposal.input.path);
154	  const filePath = path.join(proposal.input.root, safeRelativePath);
155	  const file = await open(filePath, 'r');
156	  try {
157	    const contents = Buffer.alloc(MAX_READ_FILE_BYTES + 1);
158	    const { bytesRead } = await file.read(contents, 0, contents.length, 0);
159	    if (bytesRead > MAX_READ_FILE_BYTES) {
160	      return {
161	        action: proposal.action,
162	        ok: false,
163	        exitCode: null,
164	        durationMs: Math.round(performance.now() - startedAt),
165	        timedOut: false,
166	        output: `File exceeds the ${MAX_READ_FILE_BYTES}-byte read limit.`,
167	        files: [],
168	      };
169	    }
170	    return {
171	      action: proposal.action,
172	      ok: true,
173	      exitCode: 0,
174	      durationMs: Math.round(performance.now() - startedAt),
175	      timedOut: false,
176	      output: contents.subarray(0, bytesRead).toString('utf8'),
177	      files: [safeRelativePath],
