224	  const successfulSearch = proposal.action === 'SEARCH_REPO' && result.exitCode === 1;
225	
226	  return {
227	    action: proposal.action,
228	    ok: !result.timedOut && (result.exitCode === 0 || successfulSearch),
229	    exitCode: result.exitCode,
230	    durationMs: Math.round(performance.now() - startedAt),
231	    timedOut: result.timedOut,
232	    output: normalizedOutput(result),
233	    files,
234	  };
235	}

