239	  if (!state.failedApproaches.includes(proposalSignature(proposal))) return proposal;
240	  return {
241	    action: 'ASK_USER',
242	    tool: null,
243	    input: null,
244	    reason: 'The same resolved candidate already failed; policy requires new information.',
245	  };
246	}
247	
248	export async function runOrchestration(
249	  initialState: AgentState,
250	  dependencies: OrchestrationDependencies,
251	  options: OrchestrationOptions = {},
252	): Promise<OrchestrationResult> {
253	  const maxIterations = options.maxIterations ?? MAX_ORCHESTRATION_ITERATIONS;
254	  if (!Number.isInteger(maxIterations) || maxIterations < 1 || maxIterations > MAX_ORCHESTRATION_ITERATIONS) {
255	    throw new Error(`Iteration limit must be between 1 and ${MAX_ORCHESTRATION_ITERATIONS}.`);
256	  }
257	
258	  const trace = await createOrchestrationTrace(initialState.repo.root);
259	  const execute = dependencies.execute ?? executeCandidate;
260	  let state = initialState;
261	  let searchResults: string[] = [];
262	
263	  for (let iteration = 1; iteration <= maxIterations; iteration += 1) {
264	    state = { ...state, iteration };
265	    const stateBefore = state;
266	    const evaluation = await dependencies.evaluate(state);
267	    const policy = applyPolicy(state, evaluation.assessment);
268	    const selected = repeatedFailureProposal(
269	      await selectCandidate(policy.selected, state, searchResults),
270	      state,
271	    );
272	    const approval = await resolveApproval(
273	      selected,
274	      state,
275	      evaluation,
276	      policy,
277	      dependencies.approve,
278	      searchResults,
279	    );
280	    const { proposal, decision } = approval;
281	    let toolResult: ToolResult | null = null;
282	    let nextState = state;
283	    let finished = false;
284	
285	    if (decision.kind === 'reject') {
286	      nextState = {
287	        ...state,
288	        observations: [...state.observations, rejectionObservation(decision)],
289	        currentGoal: 'Choose a permitted alternative after user rejection.',
290	      };
291	    } else if (proposal.action === 'ASK_USER') {
292	      const information = truncateText(
293	        (await dependencies.askForInformation(state)).trim(),
294	        MAX_OBSERVATION_LENGTH,
295	      );
296	      nextState = {
297	        ...state,
298	        observations: [
299	          ...state.observations,
300	          information ? `User supplied information: ${information}` : 'User supplied no additional information.',
301	        ],
302	        currentGoal: 'Reassess the task with the user response.',
303	      };
304	    } else if (proposal.action === 'FINISH') {
305	      finished = true;
306	      nextState = {
307	        ...state,
308	        observations: [...state.observations, 'User approved completion.'],
309	        currentGoal: 'Task complete.',
310	      };
311	    } else {
312	      toolResult = await safelyExecute(proposal, execute);
313	      if (proposal.action === 'SEARCH_REPO' && toolResult.ok) searchResults = toolResult.files;
314	      nextState = applyToolResult(state, proposal, toolResult);
315	    }
316	
317	    const reachedLimit = !finished && iteration === maxIterations;
318	    if (reachedLimit) {
319	      nextState = {
320	        ...nextState,
321	        observations: [...nextState.observations, `Stopped at the ${maxIterations}-iteration limit.`],
322	        currentGoal: 'Ask the user how to continue after the iteration limit.',
323	      };
324	    }
325	
326	    await appendOrchestrationTrace(trace, {
327	      iteration,
328	      stateBefore,
329	      evaluation,
330	      policy,
331	      proposal: { considered: approval.proposals, selected: structuredClone(proposal) },
332	      approval: decision,
333	      toolInput: proposal.input,
334	      toolResult,
335	      stateAfter: nextState,
336	    });
337	    state = nextState;
338	
339	    if (finished) {
340	      return {
341	        status: 'finished',
342	        state,
343	        tracePath: trace.path,
344	        iterations: iteration,
345	      };
346	    }
347	  }
348	
349	  return {
350	    status: 'iteration_limit',
351	    state,
352	    tracePath: trace.path,
353	    iterations: maxIterations,
354	  };
355	}

